'use client';

import { AnimatePresence, motion } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { PauseIcon, PlayIcon, StopIcon } from '@/registry/ndeko/lib/icons';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';
import { Badge } from '@/registry/ndeko/ui/badge';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { ClockGate, LiveDuration } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { BrowserFrame } from './browser';
import { formatPrice, OPERATOR, PERSON, TASK, totalOf } from './data';
import {
  INITIAL,
  isAgentHeld,
  liveFrameOf,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  shownFrameOf,
  type Actor,
  type ComputerState,
  type Frame,
} from './session';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
  holdWhile: isAgentHeld,
};

type StatusWord =
  | 'Working'
  | 'Waiting on you'
  | 'You have control'
  | 'Paused'
  | 'Done'
  | 'Stopped';

function statusWordOf(state: ComputerState): StatusWord {
  if (state.status === 'stopped') {
    return 'Stopped';
  }
  if (state.status === 'done') {
    return 'Done';
  }
  if (state.approval === 'pending') {
    return 'Waiting on you';
  }
  if (state.control === 'person') {
    return 'You have control';
  }
  if (state.isPaused) {
    return 'Paused';
  }
  return 'Working';
}

const STATUS_VARIANT = {
  Working: 'default',
  'Waiting on you': 'warning',
  'You have control': 'info',
  Paused: 'secondary',
  Done: 'success',
  Stopped: 'destructive',
} as const;

function pauseLabelOf(isPaused: boolean) {
  if (isPaused) {
    return 'Resume';
  }
  return 'Pause';
}

function controlLabelOf(control: Actor) {
  if (control === 'person') {
    return 'Hand back';
  }
  return 'Take over';
}

function controlVariantOf(control: Actor) {
  if (control === 'person') {
    return 'default';
  }
  return 'outline';
}

function pressedOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-[0.94]';
  }
  return undefined;
}

function rowToneOf(isShown: boolean) {
  if (isShown) {
    return 'bg-primary/10';
  }
  return 'hover:bg-foreground/[0.04]';
}

function OperatorTile() {
  const gemStyle = {
    '--gem': seriesColorOf(OPERATOR.series),
  } as React.CSSProperties;

  return (
    <span
      aria-hidden='true'
      style={gemStyle}
      className='gem-plate inline-flex size-6 shrink-0 items-center justify-center rounded-md text-[10px] font-semibold select-none'
    >
      {OPERATOR.initial}
    </span>
  );
}

function ActorMark({ actor }: { actor: Actor }) {
  if (actor === 'agent') {
    return <OperatorTile />;
  }
  return (
    <Avatar className='size-6'>
      <AvatarImage src={PERSON.avatar} alt='' />
      <AvatarFallback className='text-[9px]'>{PERSON.initials}</AvatarFallback>
    </Avatar>
  );
}

type ActionLogProps = {
  frames: Frame[];
  shownId: number;
  onView: (index: number) => void;
};

function ActionLog({ frames, shownId, onView }: ActionLogProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const rowPresence = rowPresenceOf(shouldReduceMotion);

  return (
    <ol aria-label='Actions' className='flex flex-col'>
      <AnimatePresence initial={false}>
        {frames.map((frame) => (
          <motion.li
            key={frame.id}
            className='overflow-hidden'
            {...rowPresence}
          >
            <button
              type='button'
              aria-current={frame.id === shownId}
              onClick={() => onView(frame.id)}
              className={cn(
                'focus-visible:ring-ring/25 flex min-h-10 w-full cursor-pointer items-center gap-2.5 rounded-lg px-2 py-1.5 text-start text-[13px] transition-colors duration-150 outline-none focus-visible:ring-[3px]',
                rowToneOf(frame.id === shownId)
              )}
            >
              <ActorMark actor={frame.actor} />
              <span className='min-w-0 flex-1 leading-snug'>{frame.text}</span>
              <span className='text-muted-foreground w-4 shrink-0 text-end text-xs tabular-nums'>
                {frame.id + 1}
              </span>
            </button>
          </motion.li>
        ))}
      </AnimatePresence>
    </ol>
  );
}

export default function AgentReview04() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const shouldReduceMotion = usePrefersReducedMotion();
  const rowPresence = rowPresenceOf(shouldReduceMotion);
  const live = liveFrameOf(state);
  const shown = shownFrameOf(state);
  const lastIndex = state.frames.length - 1;
  const isFollowing = state.viewed === null;
  const isRunning = state.status === 'running';
  const isPending = state.approval === 'pending';
  const hasControl = state.control === 'person';
  const isLiveView = isFollowing && isRunning;
  const canAct = hasControl && isLiveView;
  const isAgentWaiting = hasControl || state.isPaused;
  const canPause = isRunning && !hasControl;
  const statusWord = statusWordOf(state);
  const amount = formatPrice(totalOf(live.period, live.hasAddon));
  const isOver = isFinished || !isRunning;
  const canReplay = isOver && !isAutoplaying;
  const message = spokenUnless(isAutoplaying, `${statusWord}. ${live.text}`);
  const clock = {
    startedAt: state.startedAt ?? undefined,
    endedAt: state.endedAt ?? undefined,
  };

  function toggleControl() {
    if (hasControl) {
      act({ type: 'handedBack' });
      return;
    }
    act({ type: 'tookOver' });
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container min-h-dvh w-full p-3 @3xl:p-6'
      >
        <div className='mx-auto flex max-w-5xl flex-col gap-4'>
          <header className='flex flex-wrap items-center gap-x-3 gap-y-2'>
            <OperatorTile />
            <div className='flex min-w-40 flex-1 flex-col leading-tight'>
              <h1 className='text-sm font-medium'>{TASK}</h1>
              <span className='text-muted-foreground text-xs'>
                {OPERATOR.name}, in a browser it controls
              </span>
            </div>
            <Badge variant={STATUS_VARIANT[statusWord]}>
              <Swap swapKey={statusWord}>{statusWord}</Swap>
            </Badge>
            <LiveDuration
              item={clock}
              isRunning={isRunning}
              className='text-muted-foreground w-12 text-end text-[13px]'
            />
            {isRunning && (
              <Button
                type='button'
                variant='destructive'
                size='sm'
                onClick={() => act({ type: 'stopped' })}
              >
                <StopIcon />
                Stop
              </Button>
            )}
            <ReplayButton
              isShown={canReplay}
              onReplay={restart}
              label='Replay the session'
            />
          </header>

          <div className='flex flex-col gap-4 @3xl:flex-row @3xl:items-start'>
            <section
              aria-label='Browser'
              className='flex min-w-0 flex-1 flex-col gap-3'
            >
              <BrowserFrame
                frame={shown}
                isAgentWaiting={isAgentWaiting}
                canAct={canAct}
                isAddonPressed={pressed === 'addon'}
                onToggleAddon={() => act({ type: 'addon' })}
                onPeriodChange={(period) => act({ type: 'period', period })}
              />
              <div className='flex flex-wrap items-center gap-x-3 gap-y-2'>
                <label className='flex min-w-48 flex-1 items-center gap-3 text-xs'>
                  <span className='text-muted-foreground w-24 shrink-0 tabular-nums'>
                    Frame {shown.id + 1} of {state.frames.length}
                  </span>
                  <input
                    type='range'
                    min={0}
                    max={lastIndex}
                    step={1}
                    value={shown.id}
                    aria-label='Frame'
                    onChange={(event) =>
                      act({ type: 'viewed', index: Number(event.target.value) })
                    }
                    className='accent-primary h-4 min-w-0 flex-1 cursor-pointer'
                  />
                </label>
                {!isFollowing && (
                  <Button
                    type='button'
                    variant='ghost'
                    size='sm'
                    onClick={() => act({ type: 'viewed', index: null })}
                    className='text-primary-ink'
                  >
                    Back to live
                  </Button>
                )}
                <Button
                  type='button'
                  variant='outline'
                  size='sm'
                  disabled={!canPause}
                  onClick={() => act({ type: 'paused' })}
                >
                  <Swap swapKey={String(state.isPaused)}>
                    {state.isPaused && <PlayIcon />}
                    {!state.isPaused && <PauseIcon />}
                  </Swap>
                  {pauseLabelOf(state.isPaused)}
                </Button>
                <Button
                  type='button'
                  variant={controlVariantOf(state.control)}
                  size='sm'
                  disabled={!isRunning}
                  onClick={toggleControl}
                  className={pressedOf(pressed === 'takeover')}
                >
                  <Swap swapKey={state.control}>
                    {controlLabelOf(state.control)}
                  </Swap>
                </Button>
              </div>
              {hasControl && (
                <p className='bg-info/10 text-info-foreground rounded-lg px-3 py-2 text-[13px] transition-opacity duration-300 starting:opacity-0'>
                  You have the controls: change the form in the browser above.{' '}
                  {OPERATOR.name} waits until you hand back.
                </p>
              )}
            </section>

            <section
              aria-label='Session log'
              className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] flex flex-col gap-2 rounded-xl p-2 shadow-[0_1px_2px_rgb(0_0_0/0.04)] @3xl:w-80 @3xl:shrink-0'
            >
              <AnimatePresence initial={false}>
                {isPending && (
                  <motion.div
                    key='approval'
                    className='overflow-hidden'
                    {...rowPresence}
                  >
                    <div className='bg-warning/10 flex flex-col gap-3 rounded-lg p-3'>
                      <div className='flex items-center gap-2.5'>
                        <BrandTile brand='visa' size='lg' title='Visa' />
                        <div className='flex min-w-0 flex-col leading-tight'>
                          <h2 className='text-sm font-medium'>Pay {amount}</h2>
                          <span className='text-warning-foreground text-xs'>
                            Card ending 4242, cannot be undone
                          </span>
                        </div>
                      </div>
                      <div className='flex items-center justify-end gap-2'>
                        <Button
                          type='button'
                          variant='outline'
                          size='sm'
                          onClick={() =>
                            act({ type: 'decided', decision: 'denied' })
                          }
                        >
                          Deny
                        </Button>
                        <Button
                          type='button'
                          size='sm'
                          onClick={() =>
                            act({ type: 'decided', decision: 'approved' })
                          }
                          className={cn(
                            pressedOf(pressed === 'allow'),
                            pressed === 'allow' && 'bg-primary/85'
                          )}
                        >
                          Allow the payment
                        </Button>
                      </div>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
              <h2 className='text-muted-foreground px-2 pt-1 text-xs'>
                Actions, synced to the frames
              </h2>
              <ActionLog
                frames={state.frames}
                shownId={shown.id}
                onView={(index) => act({ type: 'viewed', index })}
              />
            </section>
          </div>
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { useLayoutEffect, useRef } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import {
  CheckIcon,
  LockIcon,
  MousePointerIcon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { LetterTile } from '@/registry/ndeko/ui/letter-tile';
import { StatusOrb } from '@/registry/ndeko/ui/status-orb';

import {
  ADDON_PRICE,
  DOMAINS,
  formatPrice,
  OPERATOR,
  PAGE_URL,
  PRICE_FORMAT,
  SITE,
  totalOf,
  type Period,
  type PointerTarget,
} from './data';
import type { Frame } from './session';

const DRAWN_BUTTON =
  'bg-primary text-primary-foreground inline-flex h-7 items-center rounded-full px-3 font-medium';

type FormHandlers = {
  /** True while the person has the controls of the live frame. */
  canAct: boolean;
  isAddonPressed: boolean;
  onToggleAddon: () => void;
  onPeriodChange: (period: Period) => void;
};

function ListPage() {
  return (
    <div className='flex flex-col gap-3'>
      <h3 className='text-sm font-semibold'>Domains</h3>
      <ul className='flex flex-col'>
        {DOMAINS.map((domain) => (
          <li
            key={domain.name}
            data-target={targetOfDomain(domain.isDue)}
            className='odd:bg-foreground/[0.03] flex h-9 items-center justify-between gap-2 rounded-md px-2'
          >
            <span className='truncate font-medium'>{domain.name}</span>
            {domain.isDue && <Badge variant='warning'>{domain.note}</Badge>}
            {!domain.isDue && (
              <span className='text-muted-foreground'>{domain.note}</span>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}

function targetOfDomain(isDue: boolean): PointerTarget | undefined {
  if (isDue) {
    return 'row';
  }
  return undefined;
}

function DomainPage() {
  return (
    <div className='flex flex-col items-start gap-3'>
      <h3 className='text-sm font-semibold'>tallis.example</h3>
      <p className='text-muted-foreground'>
        Registered until 12 November 2026. Renewal is not automatic.
      </p>
      <span data-target='renew' className={DRAWN_BUTTON}>
        Renew
      </span>
    </div>
  );
}

function periodToneOf(isSelected: boolean) {
  if (isSelected) {
    return 'bg-card hairline-ring ring-foreground/15 shadow-[0_1px_2px_rgb(0_0_0/0.06)] dark:bg-foreground/[0.1]';
  }
  return 'text-muted-foreground';
}

function boxToneOf(isChecked: boolean) {
  if (isChecked) {
    return 'bg-primary text-primary-foreground';
  }
  return 'hairline-ring ring-foreground/30';
}

function pressedOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-[0.96] bg-foreground/[0.08]';
  }
  return undefined;
}

const PERIODS: { period: Period; label: string }[] = [
  { period: 1, label: '1 year' },
  { period: 2, label: '2 years' },
];

function RenewPage({
  frame,
  canAct,
  isAddonPressed,
  onToggleAddon,
  onPeriodChange,
}: FormHandlers & { frame: Frame }) {
  const total = totalOf(frame.period, frame.hasAddon);

  return (
    <div className='flex flex-col gap-3'>
      <h3 className='text-sm font-semibold'>Renew tallis.example</h3>
      <div
        role='group'
        aria-label='Period'
        data-target='period'
        className='bg-foreground/[0.05] flex w-fit gap-0.5 rounded-lg p-0.5'
      >
        {PERIODS.map((option) => (
          <button
            key={option.period}
            type='button'
            aria-pressed={frame.period === option.period}
            disabled={!canAct}
            onClick={() => onPeriodChange(option.period)}
            className={cn(
              'focus-visible:ring-ring/25 h-6 rounded-md px-2.5 transition-colors duration-150 outline-none focus-visible:ring-[3px] enabled:cursor-pointer',
              periodToneOf(frame.period === option.period)
            )}
          >
            {option.label}
          </button>
        ))}
      </div>
      <button
        type='button'
        role='checkbox'
        aria-checked={frame.hasAddon}
        disabled={!canAct}
        onClick={onToggleAddon}
        className={cn(
          'focus-visible:ring-ring/25 enabled:hover:bg-foreground/[0.04] -mx-1.5 flex h-8 w-fit items-center gap-2 rounded-md px-1.5 transition-[background-color,scale] duration-150 outline-none focus-visible:ring-[3px] enabled:cursor-pointer',
          pressedOf(isAddonPressed)
        )}
      >
        <span
          className={cn(
            'flex size-4 items-center justify-center rounded-[5px] transition-colors duration-150',
            boxToneOf(frame.hasAddon)
          )}
        >
          {frame.hasAddon && <CheckIcon className='size-3' strokeWidth={2.5} />}
        </span>
        Privacy protection, {formatPrice(ADDON_PRICE)} a year
      </button>
      <div className='flex items-end justify-between gap-3'>
        <div className='flex flex-col'>
          <span className='text-muted-foreground'>Total, illustrative</span>
          <MotionNumber
            value={total}
            locale='en-IE'
            format={PRICE_FORMAT}
            className='text-2xl leading-none font-semibold'
          />
        </div>
        <span data-target='pay' className={DRAWN_BUTTON}>
          Pay
        </span>
      </div>
    </div>
  );
}

function DonePage() {
  return (
    <div className='m-auto flex flex-col items-center gap-3 text-center'>
      <StatusOrb tone='success' />
      <h3 className='text-sm font-semibold'>Renewed until 12 November 2027</h3>
      <p className='text-muted-foreground'>
        A receipt was sent to the account email.
      </p>
    </div>
  );
}

function waitingToneOf(isWaiting: boolean) {
  if (isWaiting) {
    return 'opacity-40';
  }
  return 'opacity-100';
}

function pointerWordOf(isWaiting: boolean) {
  if (isWaiting) {
    return `${OPERATOR.name} waits`;
  }
  return OPERATOR.name;
}

type BrowserFrameProps = FormHandlers & {
  frame: Frame;
  /** The agent's pointer dims while it waits for the person. */
  isAgentWaiting: boolean;
};

export function BrowserFrame({
  frame,
  isAgentWaiting,
  ...form
}: BrowserFrameProps) {
  const viewportRef = useRef<HTMLDivElement>(null);
  const pointerRef = useRef<HTMLSpanElement>(null);
  const gemStyle = {
    '--gem': seriesColorOf(OPERATOR.series),
  } as React.CSSProperties;
  const pointerStyle = { color: seriesColorOf(OPERATOR.series) };
  const target = frame.pointer;
  const frameId = frame.id;

  useLayoutEffect(() => {
    const viewport = viewportRef.current;
    const pointer = pointerRef.current;
    if (!viewport || !pointer) {
      return;
    }
    const place = () => {
      const element = viewport.querySelector(`[data-target='${target}']`);
      if (!element) {
        pointer.style.opacity = '0';
        return;
      }
      const bounds = viewport.getBoundingClientRect();
      const box = element.getBoundingClientRect();
      const x = box.left - bounds.left + box.width * 0.6;
      const y = box.top - bounds.top + box.height * 0.55;
      pointer.style.translate = `${x}px ${y}px`;
      pointer.style.opacity = '';
    };
    place();
    const observer = new ResizeObserver(place);
    observer.observe(viewport);
    return () => observer.disconnect();
  }, [target, frameId]);

  return (
    <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] overflow-hidden rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
      <div className='bg-foreground/[0.03] flex h-10 items-center gap-2 px-3'>
        <LetterTile initial={SITE.initial} />
        <div className='bg-card dark:bg-foreground/[0.05] flex h-6 min-w-0 flex-1 items-center gap-1.5 rounded-full px-2.5 text-xs'>
          <LockIcon className='text-muted-foreground size-3 shrink-0' />
          <span className='truncate'>{PAGE_URL[frame.page]}</span>
        </div>
      </div>
      <div
        ref={viewportRef}
        aria-label={`Controlled browser, ${SITE.name}`}
        className='relative flex min-h-[15.5rem] flex-col overflow-hidden p-4 text-xs'
      >
        {frame.page === 'blank' && (
          <p className='text-muted-foreground m-auto'>Opening the browser</p>
        )}
        {frame.page === 'list' && <ListPage />}
        {frame.page === 'domain' && <DomainPage />}
        {frame.page === 'renew' && <RenewPage frame={frame} {...form} />}
        {frame.page === 'done' && <DonePage />}
        <span
          ref={pointerRef}
          aria-hidden='true'
          className={cn(
            'pointer-events-none absolute top-0 left-0 flex items-start transition-[translate,opacity] duration-500 ease-(--ease-in-out-strong) motion-reduce:transition-none',
            waitingToneOf(isAgentWaiting)
          )}
        >
          <MousePointerIcon
            style={pointerStyle}
            className='size-4 fill-current'
          />
          <span
            style={gemStyle}
            className='gem-plate mt-3 rounded-full px-1.5 py-0.5 text-[10px] font-medium whitespace-nowrap'
          >
            {pointerWordOf(isAgentWaiting)}
          </span>
        </span>
      </div>
    </div>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';

import {
  AGENT_MOVES,
  PAY_MOVE,
  type PageId,
  type Period,
  type PointerTarget,
} from './data';

export type Actor = 'agent' | 'person';

export type Frame = {
  id: number;
  actor: Actor;
  text: string;
  page: PageId;
  pointer: PointerTarget | null;
  period: Period;
  hasAddon: boolean;
};

export type ApprovalStatus = 'none' | 'pending' | 'approved' | 'denied';

export type SessionStatus = 'running' | 'done' | 'stopped';

export type ComputerState = {
  status: SessionStatus;
  frames: Frame[];
  movesDone: number;
  control: Actor;
  isPaused: boolean;
  approval: ApprovalStatus;
  /** The frame being looked at, or null to follow the live one. */
  viewed: number | null;
  startedAt: number | null;
  endedAt: number | null;
};

export type ComputerAction =
  | { type: 'started' }
  | { type: 'moved' }
  | { type: 'paused' }
  | { type: 'tookOver' }
  | { type: 'handedBack' }
  | { type: 'addon' }
  | { type: 'period'; period: Period }
  | { type: 'decided'; decision: 'approved' | 'denied' }
  | { type: 'stopped' }
  | { type: 'viewed'; index: number | null };

type Step = SessionStep<ComputerState, ComputerAction>;

const BLANK: Frame = {
  id: 0,
  actor: 'agent',
  text: 'Started a browser',
  page: 'blank',
  pointer: null,
  period: 1,
  hasAddon: true,
};

export const INITIAL: ComputerState = {
  status: 'running',
  frames: [BLANK],
  movesDone: 0,
  control: 'agent',
  isPaused: false,
  approval: 'none',
  viewed: null,
  startedAt: null,
  endedAt: null,
};

export function liveFrameOf(state: ComputerState) {
  const last = state.frames.at(-1);
  return last ?? BLANK;
}

export function shownFrameOf(state: ComputerState) {
  if (state.viewed === null) {
    return liveFrameOf(state);
  }
  return state.frames[state.viewed] ?? liveFrameOf(state);
}

export function isAgentHeld(state: ComputerState) {
  const isOver = state.status !== 'running';
  const isWaiting = state.isPaused || state.control === 'person';
  return isOver || isWaiting;
}

function withFrame(
  state: ComputerState,
  patch: Partial<Frame> & Pick<Frame, 'actor' | 'text'>
): ComputerState {
  const live = liveFrameOf(state);
  const frame: Frame = { ...live, ...patch, id: state.frames.length };
  return { ...state, frames: [...state.frames, frame] };
}

function moved(state: ComputerState, now: number): ComputerState {
  const move = AGENT_MOVES[state.movesDone];
  const isWaitingForYes = state.approval === 'pending';
  const cannotMove = isWaitingForYes || isAgentHeld(state);
  if (!move) {
    return state;
  }
  if (cannotMove) {
    return state;
  }
  const next = withFrame(state, { actor: 'agent', ...move });
  const movesDone = state.movesDone + 1;
  const isPayMove = state.movesDone === PAY_MOVE;
  if (isPayMove) {
    return { ...next, movesDone, approval: 'pending' };
  }
  const isLast = movesDone === AGENT_MOVES.length;
  if (isLast) {
    return { ...next, movesDone, status: 'done', endedAt: now };
  }
  return { ...next, movesDone };
}

function personChanged(
  state: ComputerState,
  patch: Partial<Frame>,
  text: string
): ComputerState {
  const live = liveFrameOf(state);
  const isOnForm = live.page === 'renew';
  const canAct = state.control === 'person' && state.status === 'running';
  if (!isOnForm || !canAct) {
    return state;
  }
  return withFrame(state, { ...patch, actor: 'person', text, pointer: null });
}

function addonTextOf(hasAddon: boolean) {
  if (hasAddon) {
    return 'You added privacy protection';
  }
  return 'You removed privacy protection';
}

function periodTextOf(period: Period) {
  if (period === 1) {
    return 'You chose 1 year';
  }
  return 'You chose 2 years';
}

function decided(
  state: ComputerState,
  decision: 'approved' | 'denied',
  now: number
): ComputerState {
  if (state.approval !== 'pending') {
    return state;
  }
  if (decision === 'approved') {
    return { ...state, approval: 'approved' };
  }
  const denied = withFrame(state, {
    actor: 'person',
    text: 'You denied the payment. Nothing was charged',
    pointer: null,
  });
  return { ...denied, approval: 'denied', status: 'stopped', endedAt: now };
}

function stopped(state: ComputerState, now: number): ComputerState {
  if (state.status !== 'running') {
    return state;
  }
  const next = withFrame(state, {
    actor: 'person',
    text: 'You stopped the session',
    pointer: null,
  });
  return { ...next, status: 'stopped', approval: 'none', endedAt: now };
}

function viewed(state: ComputerState, index: number | null): ComputerState {
  const last = state.frames.length - 1;
  const isLive = index === null || index >= last;
  if (isLive) {
    return { ...state, viewed: null };
  }
  return { ...state, viewed: Math.max(0, index) };
}

export function applyAt(
  state: ComputerState,
  action: ComputerAction,
  now: number
): ComputerState {
  switch (action.type) {
    case 'started':
      return { ...state, startedAt: now };
    case 'moved':
      return moved(state, now);
    case 'paused':
      return { ...state, isPaused: !state.isPaused };
    case 'tookOver':
      return { ...state, control: 'person', viewed: null };
    case 'handedBack':
      return { ...state, control: 'agent' };
    case 'addon': {
      const hasAddon = !liveFrameOf(state).hasAddon;
      return personChanged(state, { hasAddon }, addonTextOf(hasAddon));
    }
    case 'period':
      return personChanged(
        state,
        { period: action.period },
        periodTextOf(action.period)
      );
    case 'decided':
      return decided(state, action.decision, now);
    case 'stopped':
      return stopped(state, now);
    case 'viewed':
      return viewed(state, action.index);
  }
}

export function reducer(state: ComputerState, action: ComputerAction) {
  return applyAt(state, action, Date.now());
}

function hasDecided(state: ComputerState) {
  return state.approval !== 'pending';
}

/** A request that waits on a person is answered by the demonstration after this long. */
const DECIDE_AFTER_MS = 2500;

export const SCRIPT: Step[] = [
  { after: 500, action: { type: 'started' } },
  { after: 700, action: { type: 'moved' } },
  { after: 1600, action: { type: 'moved' } },
  { after: 1600, action: { type: 'moved' } },
  { after: 1700, by: 'demo', press: 'takeover', action: { type: 'tookOver' } },
  { after: 1500, by: 'demo', press: 'addon', action: { type: 'addon' } },
  {
    after: 1700,
    by: 'demo',
    press: 'takeover',
    action: { type: 'handedBack' },
  },
  { after: 1300, action: { type: 'moved' } },
  {
    after: DECIDE_AFTER_MS,
    by: 'person',
    press: 'allow',
    action: { type: 'decided', decision: 'approved' },
    isAnswered: hasDecided,
  },
  { after: 1300, action: { type: 'moved' } },
];

function restingOf() {
  let state = INITIAL;
  let now = 1000;
  for (const step of SCRIPT) {
    now += step.after;
    state = applyAt(state, step.action, now);
  }
  return state;
}

export const RESTING = restingOf();

